select 'backtesting-your-strategy' as slug, (slug = 'backtesting-your-strategy'
   and title = $q$Backtesting Your Strategy$q$
   and md5(content) = 'aa8e5847f3a18750dce13c154b8f8ac0'
   and learning_objective is not distinct from $q$Understand what backtesting is and practice applying a trading rule consistently to historical price action.$q$
   and key_takeaways = $q$["Backtesting tests your rules against historical data before you risk real money.", "A backtest only proves useful if you apply your rule consistently — skipping non-matching setups is as important as taking matching ones."]$q$::jsonb
   and coalesce(examples,'null'::jsonb) = $q$[]$q$::jsonb
   and coalesce(interactive_config,'null'::jsonb) = $q${"scenarios": [{"chart": [{"c": 51, "h": 54, "l": 30, "o": 52}], "options": ["Enter — this matches the rule", "Skip — doesn't match", "Wait for a different pattern", "Double the position size"], "question": "Your rule is \"buy on a bullish pin bar at support.\" This candle formed right at support (see chart). What do you do?", "explanation": "A backtest only works if you follow your own rule consistently — this is a textbook match.", "correctIndex": 0}, {"chart": [{"c": 42, "h": 45, "l": 38, "o": 41}], "options": ["Skip — no signal here", "Enter anyway, it looks bullish", "Enter with a smaller size", "Change your rule on the spot"], "question": "This candle formed in the middle of a range, not at any support or resistance zone (see chart). Your rule is \"buy on a bullish pin bar at support.\" What do you do?", "explanation": "Skipping trades that don't match your rule is just as important as taking the ones that do — that discipline is what backtesting builds.", "correctIndex": 0}, {"chart": [{"c": 49, "h": 70, "l": 46, "o": 48}], "options": ["Skip — wrong signal type for this system", "Enter — it's still a reversal pattern", "Enter but reverse the direction", "Skip the whole session"], "question": "This is a shooting star at resistance (see chart). Your rule is \"buy on a bullish pin bar at support.\" What do you do?", "explanation": "A shooting star at resistance is a bearish signal — it doesn't match a buy-only rule, even though it's a valid pattern.", "correctIndex": 0}, {"icon": "📈", "options": ["A positive expectancy in the test — worth trying small next, max 1% risk (not guaranteed)", "No — below 50% win rate means it loses", "Cannot tell without more data", "Only if you increase the RR further"], "question": "Your backtest shows a 42% win rate at 1:2 RR over 100 trades. What does this backtest suggest?", "explanation": "42% win rate at 1:2 RR: 42 wins x 2R = 84R, 58 losses x 1R = 58R. Net = +26R over those 100 test trades: a positive expectancy even under a 50% win rate, but not a guarantee of future results. If you try it, start small on a cents account with max 1% risk and a stop loss on every trade.", "correctIndex": 0}, {"icon": "🔬", "options": ["Test whether your rules showed an edge on historical data, without risking real money", "Guarantee your strategy will win in the future", "Make trading feel more exciting", "Copy what other traders are doing"], "question": "The main point of backtesting before you risk real money is to:", "explanation": "Backtesting doesn't guarantee future results, but it tells you whether your rules had any edge at all before you risk real capital on them.", "correctIndex": 0}]}$q$::jsonb) as ok from public.lessons where id = 'd0f2dc2d-bad5-4b7e-9bbb-6a9efd672d65'
union all
select 'pips-lots-and-leverage' as slug, (slug = 'pips-lots-and-leverage'
   and title = $q$Pips, Lots & Leverage$q$
   and md5(content) = 'e26e50ab245f884e1a021fa12a08620e'
   and learning_objective is not distinct from $q$Calculate pip value and position size for gold and understand how leverage amplifies risk.$q$
   and key_takeaways = $q$["In the common convention, 1 standard lot of gold = 100 oz, and a $0.01 move = $1 per lot; check your broker's specs.", "Leverage changes margin, not the value of each move, and it makes oversized positions dangerously easy.", "Size every trade from max 1% risk and your stop distance, never from available leverage."]$q$::jsonb
   and coalesce(examples,'null'::jsonb) = $q$[{"note": "Convention note: GFX lessons treat a $0.01 move in XAUUSD as 1 pip, and 1 standard lot as 100 oz, so a $0.01 move = $1 per standard lot. Many brokers define a gold pip differently (often $0.10) and contract sizes can vary. Always check your own broker's contract specifications.", "steps": ["Hypothetical account: $1,000. Max risk 1% = $10.", "Plan: buy XAUUSD at 2,350.00 with stop loss at 2,345.00 → stop distance $5.00 (500 pips at $0.01 = 1 pip).", "Loss per 0.01 lot (1 oz) if stopped = $5.00 × 1 = $5.", "Lot size = $10 ÷ $5 per 0.01 lot = 0.02 lot (2 oz).", "Check: $5.00 × 2 oz = $10 = 1% of the account. A 1-lot position would risk $500 (50% of the account), which leverage might allow but your risk rule never should."], "title": "Sizing a gold trade with 1% risk", "disclaimer": "All prices are illustrative and hypothetical, not real quotes, forecasts, or results.", "hypothetical": true}]$q$::jsonb
   and coalesce(interactive_config,'null'::jsonb) = $q${"scenarios": [{"options": ["100 oz", "10 oz", "1 oz", "0.01 oz"], "question": "Under the common convention, what is 0.01 lot of XAUUSD?", "explanation": "1 standard lot = 100 oz, so 0.01 lot = 1 oz. Check your broker's contract specs.", "correctIndex": 2}, {"options": ["0.02 lot", "0.20 lot", "1 lot", "2 lots"], "question": "Hypothetical: $1,000 account, 1% risk, stop distance $5.00. What lot size?", "explanation": "Risk $10 ÷ ($5.00 × 1 oz per 0.01 lot = $5) = 2 × 0.01 = 0.02 lot.", "correctIndex": 0}, {"options": ["1%", "1-2%", "5%", "Depends on leverage"], "question": "What is the maximum risk per trade under the GFX standard?", "explanation": "The GFX standard is max 1% per trade, always with a stop loss. Leverage should never decide your size.", "correctIndex": 0}]}$q$::jsonb) as ok from public.lessons where id = 'a1caf3d9-689a-4696-9443-f9f947a1dd05'
union all
select 'candlestick-anatomy' as slug, (slug = 'candlestick-anatomy'
   and title = $q$Candlestick Anatomy$q$
   and md5(content) = '6558bfa684e284247300583f10471488'
   and learning_objective is not distinct from $q$Read the open, high, low and close of a candlestick.$q$
   and key_takeaways = $q$["Each candle shows open, high, low and close (OHLC) for one time period.", "The body shows open-to-close; wicks show the high and low reached.", "Read candles in context, since a single candle is never a guaranteed signal."]$q$::jsonb
   and coalesce(examples,'null'::jsonb) = $q$[{"note": "All prices are illustrative and hypothetical, not real quotes, forecasts, or results.", "steps": ["Open 2,350.00, High 2,356.00, Low 2,347.00, Close 2,354.00.", "Close is above open → bullish candle. Body = 2,354.00 − 2,350.00 = $4.00.", "Upper wick = 2,356.00 − 2,354.00 = $2.00; lower wick = 2,350.00 − 2,347.00 = $3.00.", "Total range = 2,356.00 − 2,347.00 = $9.00. On 0.01 lot (1 oz), that hour's full range equals $9."], "title": "Reading one hypothetical 1-hour gold candle", "disclaimer": "All prices are illustrative and hypothetical, not real quotes, forecasts, or results.", "hypothetical": true}]$q$::jsonb
   and coalesce(interactive_config,'null'::jsonb) = $q${"presets": [{"c": 2322, "h": 2325, "l": 2298, "o": 2300, "label": "Strong Bullish"}, {"c": 2300.5, "h": 2312, "l": 2288, "o": 2300, "label": "Doji"}, {"c": 2298, "h": 2300, "l": 2278, "o": 2290, "label": "Bullish Pin Bar"}, {"c": 2300, "h": 2325, "l": 2298, "o": 2322, "label": "Bearish"}, {"c": 2297.5, "h": 2325, "l": 2296, "o": 2306, "label": "Shooting Star"}], "scenarios": [{"options": ["Bearish", "Bullish", "Neutral by definition", "Invalid"], "question": "A candle opens at 2,350.00 and closes at 2,354.00. It is…", "explanation": "It closed above its open, so it is a bullish candle.", "correctIndex": 1}, {"options": ["$4", "$6", "$9", "$11"], "question": "High 2,356.00, Low 2,347.00. What is the candle's range?", "explanation": "Range = high − low = 2,356.00 − 2,347.00 = $9.00.", "correctIndex": 2}, {"options": ["Price never went higher than the body", "Buyers pushed price up but it was pushed back down before the close", "The market was closed", "A guaranteed reversal"], "question": "What does a long upper wick usually show?", "explanation": "The wick shows price traded higher but did not hold there; it is information, not a guarantee.", "correctIndex": 1}], "showAnatomyDiagram": true, "includeFreehandPractice": true}$q$::jsonb) as ok from public.lessons where id = 'd7926520-c96b-4d61-bd1e-0078b3b718a8'
union all
select 'stocks-vs-forex-vs-gold' as slug, (slug = 'stocks-vs-forex-vs-gold'
   and title = $q$Stocks vs Forex vs Gold$q$
   and md5(content) = '8cb39725effbc3cbd20ebbcc5f1d1464'
   and learning_objective is not distinct from $q$Compare stocks, forex and gold, and understand what moves the gold price.$q$
   and key_takeaways = $q$["Stocks follow companies, forex follows currencies and economies, and gold follows fear, inflation, rates and the US dollar.", "Gold is liquid and trades almost 24/5, but it can move very fast, especially around major US news.", "Fast markets require smaller positions, a stop loss on every trade, and starting small."]$q$::jsonb
   and coalesce(examples,'null'::jsonb) = $q$[{"note": "Convention note: GFX lessons treat a $0.01 move in XAUUSD as 1 pip, and 1 standard lot as 100 oz, so a $0.01 move = $1 per standard lot. Many brokers define a gold pip differently (often $0.10) and contract sizes can vary. Always check your own broker's contract specifications.", "steps": ["Hypothetical: XAUUSD is at 2,340.00 a few minutes before a US inflation report.", "The report surprises the market and gold jumps to 2,352.00 within minutes, a $12.00 move.", "On 1 standard lot (100 oz), a $12.00 move equals $1,200; on 0.01 lot (1 oz), it equals $12.", "The same move in the opposite direction would be a loss of the same size, which is why position size and a stop loss matter."], "title": "How a news spike can look", "disclaimer": "All prices are illustrative and hypothetical, not real quotes, forecasts, or results.", "hypothetical": true}]$q$::jsonb
   and coalesce(interactive_config,'null'::jsonb) = $q${"scenarios": [{"options": ["A company's quarterly earnings", "Inflation and interest-rate expectations", "The number of followers a trader has", "The color of the chart"], "question": "Which factor commonly moves the gold price?", "explanation": "Gold often reacts to inflation, interest-rate expectations, risk sentiment and the US dollar.", "correctIndex": 1}, {"options": ["$0.12", "$1.20", "$12", "$1,200"], "question": "Hypothetically, gold moves $12.00. What is the change on 0.01 lot (1 oz)?", "explanation": "0.01 lot = 1 oz in the common convention, so a $12.00 move changes the position by $12. (Conventions vary by broker.)", "correctIndex": 2}, {"options": ["Use a large lot to catch big moves", "Trade every news release", "Use small positions, always a stop loss, and start small", "Remove the stop loss so you aren't stopped out"], "question": "What is a sensible beginner approach to a fast market like gold?", "explanation": "Speed means losses can grow quickly. Small size, a stop loss on every trade, and max 1% risk are the sensible starting point.", "correctIndex": 2}]}$q$::jsonb) as ok from public.lessons where id = '5698278e-2b5c-4706-8032-50cd517df741'
