select 'bull-market-vs-bear-market' as slug, (slug = 'bull-market-vs-bear-market'
   and title = $q$Bull Market vs Bear Market$q$
   and md5(content) = '8ffe115d75865b1b85547f8513942011'
   and learning_objective is not distinct from $q$Recognize bullish, bearish and sideways conditions on a gold chart.$q$
   and key_takeaways = $q$["Bull markets show higher highs and higher lows; bear markets show lower highs and lower lows.", "Sideways ranges are common, and forcing trades in choppy markets is a frequent beginner mistake.", "Trends can end without warning, so every trade still needs a stop loss."]$q$::jsonb
   and coalesce(examples,'null'::jsonb) = $q$[{"note": "All prices are illustrative and hypothetical, not real quotes, forecasts, or results.", "steps": ["Hypothetical swings on XAUUSD: low 2,320 → high 2,340 → low 2,330 → high 2,352 → low 2,341.", "Each high is higher (2,340 → 2,352) and each low is higher (2,320 → 2,330 → 2,341): this is a bullish structure.", "If price later breaks below 2,341 and then fails to make a new high, the bullish structure may be ending.", "A stop loss placed below a recent higher low (e.g. below 2,341) limits the loss if the trend fails."], "title": "Spotting higher highs and higher lows", "disclaimer": "All prices are illustrative and hypothetical, not real quotes, forecasts, or results.", "hypothetical": true}]$q$::jsonb
   and coalesce(interactive_config,'null'::jsonb) = $q${"scenarios": [{"options": ["Lower highs and lower lows", "Higher highs and higher lows", "Flat line", "Random dots"], "question": "Which pattern describes a bull market?", "explanation": "A bullish trend makes higher highs and higher lows.", "correctIndex": 1}, {"options": ["Lower lows, bearish", "Higher lows, bullish structure", "Nothing at all", "Guaranteed profit if you buy"], "question": "Hypothetical lows: 2,320, 2,330, 2,341. What do they suggest?", "explanation": "Rising lows suggest a bullish structure, but nothing is guaranteed.", "correctIndex": 1}, {"options": ["Trends can reverse at any time", "Brokers require it for fun", "It increases profit", "It is not needed with the trend"], "question": "Why use a stop loss even when trading with the trend?", "explanation": "Trends can end suddenly; a stop loss caps the loss if the market turns.", "correctIndex": 0}]}$q$::jsonb) as ok from public.lessons where id = 'ad3d52a1-544d-47e0-91d9-337503678387'
union all
select 'position-sizing-and-lot-calculation' as slug, (slug = 'position-sizing-and-lot-calculation'
   and title = $q$Position Sizing & Lot Calculation$q$
   and md5(content) = '2caba5d1af082aa985133efb09999934'
   and learning_objective is not distinct from $q$Calculate the correct lot size for any trade based on account balance, risk percentage, and stop loss distance.$q$
   and key_takeaways = $q$["Never risk more than 1% of your account on a single trade.", "Lot size = Risk amount divided by (Stop Loss pips x Pip Value) — never guess it."]$q$::jsonb
   and coalesce(examples,'null'::jsonb) = $q$[]$q$::jsonb
   and coalesce(interactive_config,'null'::jsonb) = $q${"scenarios": [{"options": ["$2", "$20", "$200", "$1,000"], "question": "Hypothetical: your account is $2,000. Under the GFX 1% rule, what is the most you may risk on one trade?", "explanation": "1% of $2,000 = $20. That is the maximum planned loss if your stop loss is hit.", "correctIndex": 1}, {"options": ["$0.65 (65 pips)", "$6.50 (650 pips)", "$65.00 (6,500 pips)", "$3.50 (350 pips)"], "question": "Hypothetical: you plan to buy XAUUSD at 2,350.00 with a stop loss at 2,343.50. What is the stop distance?", "explanation": "2,350.00 − 2,343.50 = $6.50. With $0.01 = 1 pip, that is 650 pips. (Many brokers count a gold pip as $0.10, which would make it 65 pips; the dollar distance is the same.)", "correctIndex": 1}, {"options": ["0.03 lot", "0.04 lot", "0.30 lot", "3 lots"], "question": "Same trade: $20 max risk, $6.50 stop distance. With 1 lot = 100 oz (so 0.01 lot = 1 oz and a $0.01 move = $1 per lot), what is the largest lot size within the rule, in 0.01-lot steps?", "explanation": "Loss per 0.01 lot = $6.50 × 1 oz = $6.50. $20 ÷ $6.50 ≈ 3.08 → round DOWN to 3 × 0.01 = 0.03 lot (risk $19.50). 0.04 lot would risk $26, which is over 1%.", "correctIndex": 0}]}$q$::jsonb) as ok from public.lessons where id = '7246c3d7-a7bb-4945-9c40-9758b4cbd553'
union all
select 'what-is-the-financial-market' as slug, (slug = 'what-is-the-financial-market'
   and title = $q$What is the Financial Market?$q$
   and md5(content) = 'b060d7825da63d98e7c78d95ea105616'
   and learning_objective is not distinct from $q$Understand what a financial market is, who takes part, and where gold (XAUUSD) fits in.$q$
   and key_takeaways = $q$["A financial market is where buyers and sellers exchange assets; prices move with the balance of supply and demand.", "XAUUSD is the price of one troy ounce of gold in US dollars, traded almost 24 hours a day, 5 days a week.", "Large institutions drive most price movement, so beginners should focus on learning and risk control, not prediction."]$q$::jsonb
   and coalesce(examples,'null'::jsonb) = $q$[{"note": "The same $2 move can be a small or large gain or loss depending on position size, which you'll learn in Level 2.", "steps": ["Suppose your platform shows XAUUSD at 2,350.00 (hypothetical).", "That means 1 troy ounce of gold costs 2,350.00 US dollars at that moment.", "If news makes more buyers step in and the price moves to 2,352.00, gold has risen by $2.00 per ounce.", "If sellers dominate and it drops to 2,348.00, gold has fallen by $2.00 per ounce."], "title": "Reading a gold price", "disclaimer": "All prices are illustrative and hypothetical, not real quotes, forecasts, or results.", "hypothetical": true}]$q$::jsonb
   and coalesce(interactive_config,'null'::jsonb) = $q${"scenarios": [{"options": ["The price of 1 gram of gold in Philippine pesos", "The price of 1 troy ounce of gold in US dollars", "A gold mining company's stock", "The exchange rate between USD and EUR"], "question": "What does XAUUSD represent?", "explanation": "XAU is the code for gold and USD for the US dollar, so XAUUSD is the price of one troy ounce of gold in dollars.", "correctIndex": 1}, {"options": ["Because the broker decides to raise it", "Because more participants want to buy than sell", "Because it is a weekday", "Because retail traders always buy"], "question": "Why does a market price usually rise?", "explanation": "Prices move with supply and demand. More buying pressure than selling pressure tends to push prices up.", "correctIndex": 1}, {"options": ["Predicting tomorrow's gold price", "Copying other people's trades", "Learning how the market works and managing risk", "Trading with as much money as possible"], "question": "What is the best focus for a beginner?", "explanation": "No one reliably predicts short-term moves. Beginners should learn the basics and manage risk: max 1% per trade, a stop loss on every trade.", "correctIndex": 2}]}$q$::jsonb) as ok from public.lessons where id = '680c3ddf-a5e5-459d-bdf3-e8f06251e1de'
union all
select 'real-money-and-your-emotions' as slug, (slug = 'real-money-and-your-emotions'
   and title = $q$Real Money and Your Emotions$q$
   and md5(content) = 'dde3513b596498c82e7b7d5cedcb063a'
   and learning_objective is not distinct from $q$Understand why real money changes your psychology, why demo results don't transfer, and how a small cents account helps you train your emotions.$q$
   and key_takeaways = $q$["The buttons are the same on demo and real accounts; the psychological weight of real money is what changes everything.", "Positive results on demo don't guarantee the same results with real money.", "Kung magte-trade ka, start small sa cents account: pera lang na kaya mong mawala. Max 1% risk per trade, laging may stop loss."]$q$::jsonb
   and coalesce(examples,'null'::jsonb) = $q$[]$q$::jsonb
   and coalesce(interactive_config,'null'::jsonb) = $q${"scenarios": [{"icon": "🧠", "options": ["Real money triggers emotions absent in demo", "Demo has better spreads", "Live execution is slower", "Demo has more indicators"], "question": "Why do traders often struggle more on live vs demo?", "explanation": "Real money triggers fear and greed at a level demo trading simply can't replicate.", "correctIndex": 0}, {"icon": "⚖️", "options": ["Real money brings real psychological pressure", "Live accounts have wider spreads by default", "Demo accounts always produce better results", "There is no real difference"], "question": "What's the main risk difference between demo and live trading?", "explanation": "The mechanics are identical — it's the psychological weight of real money that changes everything.", "correctIndex": 0}, {"icon": "🚧", "options": ["No — emotional factors on live are different", "Yes, demo results transfer directly", "Only if you use a bigger lot size live", "Yes, as long as you use the same broker"], "question": "Do positive results on demo guarantee the same results live?", "explanation": "Many traders do well on demo, then struggle with real money — which is why GFX suggests starting small with real money from the start.", "correctIndex": 0}]}$q$::jsonb) as ok from public.lessons where id = '5b957c8d-5ac5-45ee-bcbf-5bc7ec91d764'
