select 'cents-account-your-first-real-money-practice' as slug, (slug = 'cents-account-your-first-real-money-practice'
   and title = $q$Cents Account — Your First Real-Money Practice$q$
   and md5(content) = '962baa76945f184932069a19a2bb2a92'
   and learning_objective is not distinct from $q$Understand what a cents account is, why GFX suggests starting small with real money to train your emotions, and the rules: max 1% risk per trade, stop loss on every trade.$q$
   and key_takeaways = $q$["A cents account is small real money: balance shown in cents, very small lot sizes, real losses.", "Practice stop losses, 1% sizing, your written plan and journaling on every trade, kahit maliit ang account.", "Measure progress by weeks of following your plan, not by your balance or profits.", "Kung magte-trade ka, start small sa cents account: pera lang na kaya mong mawala. Max 1% risk per trade, laging may stop loss."]$q$::jsonb
   and coalesce(examples,'null'::jsonb) = $q$[{"note": "Convention note: GFX lessons treat a $0.01 move in XAUUSD as 1 pip, and 1 standard lot as 100 oz, so a $0.01 move = $1 per standard lot. Many brokers define a gold pip differently (often $0.10) and contract sizes can vary, and cents accounts use different contract sizes. Always check your own broker's contract specifications.", "steps": ["Hypothetical $1,000 account. Rule: max 1% risk ($10) per trade, stop loss always.", "Trade idea: buy XAUUSD at 2,350.00, stop 2,346.00 ($4.00 per oz). Size = $10 ÷ $4 = 2.5 oz → round down to 0.02 lot (2 oz, $8 risk).", "Journal entry: reason for entry, SL/TP levels, size, result, and a yes/no: 'Did I follow my plan?'", "At week's end, count rule-following trades, not the balance."], "title": "A week-one routine", "disclaimer": "All prices are illustrative and hypothetical, not real quotes, forecasts, or results.", "hypothetical": true}]$q$::jsonb
   and coalesce(interactive_config,'null'::jsonb) = $q${"scenarios": [{"options": ["Highest account balance", "Weeks of consistently following your plan", "Number of trades per day", "Biggest single win"], "question": "What is the best measure of progress on a cents account?", "explanation": "GFX measures readiness by process: weeks of following your rules, not profits.", "correctIndex": 1}, {"options": ["0.02 lot", "0.03 lot", "0.25 lot", "1 lot"], "question": "Hypothetical: $1,000 account, 1% risk, stop distance $4.00. Largest size within the rule (0.01-lot steps)?", "explanation": "$10 ÷ $4 per oz = 2.5 oz; round DOWN to 0.02 lot (2 oz = $8 risk). 0.03 lot would risk $12, over 1%.", "correctIndex": 0}, {"options": ["Cents accounts guarantee profits", "Small real money triggers the emotions you need to learn to manage", "Demo accounts have no charts", "There is no difference"], "question": "Why does GFX suggest a small cents account instead of only a demo?", "explanation": "Virtual money doesn't trigger fear or greed. Small real money does, so you can train your emotions while the amount at stake stays small. Losses are still real.", "correctIndex": 1}]}$q$::jsonb) as ok from public.lessons where id = '3cb8acf1-27ac-42fb-bd4d-95e5b18b00ef'
