select 'how-do-traders-make-money' as slug, (slug = 'how-do-traders-make-money'
   and title = $q$How Do Traders Make Money?$q$
   and md5(content) = '4c620553ecc5bcabef29d3c22725b6ae'
   and learning_objective is not distinct from $q$Understand how a trade can gain or lose, and why losses are a normal part of trading.$q$
   and key_takeaways = $q$["A long (buy) position gains when price rises; a short (sell) position gains when price falls, and either can lose.", "Losing trades are normal; controlling loss size (max 1% per trade) matters more than any single win.", "Costs like the spread mean a trade must move in your favor just to break even."]$q$::jsonb
   and coalesce(examples,'null'::jsonb) = $q$[{"note": "These are illustrative numbers before costs, not results. Convention note: GFX lessons treat a $0.01 move in XAUUSD as 1 pip, and 1 standard lot as 100 oz, so a $0.01 move = $1 per standard lot. Many brokers define a gold pip differently (often $0.10) and contract sizes can vary. Always check your own broker's contract specifications.", "steps": ["Hypothetical long: buy 0.01 lot (1 oz) XAUUSD at 2,350.00, stop loss at 2,345.00.", "If price rises to 2,355.00, the position is up $5.00 per oz = $5 (before costs).", "If price falls to the stop loss at 2,345.00, the position closes at a loss of $5.00 per oz = $5 (plus costs).", "Hypothetical short: sell 0.01 lot at 2,350.00; if price falls to 2,345.00 the position is up $5, if it rises to 2,355.00 it is down $5."], "title": "Long vs short on gold", "disclaimer": "All prices are illustrative and hypothetical, not real quotes, forecasts, or results.", "hypothetical": true}]$q$::jsonb
   and coalesce(interactive_config,'null'::jsonb) = $q${"scenarios": [{"options": ["When the price rises", "When the price falls", "Only on Fridays", "Never"], "question": "You sell (go short) XAUUSD. When does the position gain?", "explanation": "A short position gains when the price falls and loses when it rises.", "correctIndex": 1}, {"options": ["+$5", "-$5", "-$500", "-$0.05"], "question": "Hypothetically, you buy 0.01 lot at 2,350.00 and price drops to 2,345.00. What is the result before costs?", "explanation": "0.01 lot = 1 oz, and the price fell $5.00, so the loss is $5 before costs (common convention).", "correctIndex": 1}, {"options": ["1% of your account", "5% of your account", "Whatever feels right", "50% if you're confident"], "question": "What does GFX recommend as maximum risk per trade?", "explanation": "The GFX standard is max 1% risk per trade with a stop loss on every trade.", "correctIndex": 0}]}$q$::jsonb) as ok from public.lessons where id = '94768e3c-a60b-4fb3-be16-c2e5c5a30132'
union all
select 'what-is-a-spread' as slug, (slug = 'what-is-a-spread'
   and title = $q$What is a Spread?$q$
   and md5(content) = 'f4e8a2adf44bd54ad63895591a62053b'
   and learning_objective is not distinct from $q$Understand bid, ask and spread, and how the spread affects every trade.$q$
   and key_takeaways = $q$["Bid is the sell price, ask is the buy price, and the spread is the difference: a cost on every trade.", "Spreads vary and often widen around news, rollover and low liquidity.", "Check the spread before entering and leave room for it when placing your stop loss."]$q$::jsonb
   and coalesce(examples,'null'::jsonb) = $q$[{"note": "Convention note: GFX lessons treat a $0.01 move in XAUUSD as 1 pip, and 1 standard lot as 100 oz, so a $0.01 move = $1 per standard lot. Many brokers define a gold pip differently (often $0.10) and contract sizes can vary. Always check your own broker's contract specifications.", "steps": ["Hypothetical quote: Bid 2,350.00 / Ask 2,350.30.", "Spread = 2,350.30 − 2,350.00 = $0.30 = 30 pips (with $0.01 = 1 pip).", "On 1 standard lot (100 oz): $0.30 × 100 = $30 cost to open.", "On 0.01 lot (1 oz): $0.30 × 1 = $0.30 cost.", "Price must rise $0.30 from your buy just for the trade to break even (before other costs)."], "title": "Calculating the spread cost", "disclaimer": "All prices are illustrative and hypothetical, not real quotes, forecasts, or results.", "hypothetical": true}]$q$::jsonb
   and coalesce(interactive_config,'null'::jsonb) = $q${"scenarios": [{"options": ["$0.03", "$0.30", "$3.00", "$30.00"], "question": "Bid 2,350.00, Ask 2,350.30 (hypothetical). What is the spread?", "explanation": "2,350.30 − 2,350.00 = $0.30, which is 30 pips under the $0.01 = 1 pip convention.", "correctIndex": 1}, {"options": ["$0.30", "$3", "$30", "Nothing"], "question": "With that $0.30 spread, what is the cost on 0.01 lot (1 oz)?", "explanation": "$0.30 × 1 oz = $0.30. On 1 standard lot (100 oz) it would be $30.", "correctIndex": 0}, {"options": ["During major news and low liquidity", "Only on weekends when markets are closed", "Never, they are fixed", "When you use a stop loss"], "question": "When do spreads often widen?", "explanation": "Spreads commonly widen around major news releases, rollover and low-liquidity periods.", "correctIndex": 0}]}$q$::jsonb) as ok from public.lessons where id = '3ea5a6f7-d454-4734-8a8a-af15f8c0adca'
union all
select 'what-is-a-broker' as slug, (slug = 'what-is-a-broker'
   and title = $q$What is a Broker?$q$
   and md5(content) = '401f93b366a1a0f04eaf31313413e7be'
   and learning_objective is not distinct from $q$Understand what a broker does and how to evaluate one safely, without endorsing any provider.$q$
   and key_takeaways = $q$["A broker provides market access and earns through spreads, commissions and swaps.", "Verify regulation on the regulator's own website and understand every cost before depositing.", "Walk away from guaranteed returns, deposit pressure, or anyone offering to trade for you."]$q$::jsonb
   and coalesce(examples,'null'::jsonb) = $q$[{"note": "Convention note: GFX lessons treat a $0.01 move in XAUUSD as 1 pip, and 1 standard lot as 100 oz, so a $0.01 move = $1 per standard lot. Many brokers define a gold pip differently (often $0.10) and contract sizes can vary. Always check your own broker's contract specifications.", "steps": ["Broker A (hypothetical): spread $0.30 on XAUUSD, no commission.", "Broker B (hypothetical): spread $0.10, plus $7 commission per standard lot round trip.", "For 1 standard lot (100 oz): A costs $0.30 × 100 = $30; B costs $0.10 × 100 + $7 = $17.", "For 0.01 lot (1 oz): A costs $0.30; B costs $0.10 + $0.07 = $0.17.", "Cost is only one factor. Regulation, withdrawals and protections matter more."], "title": "Comparing costs between two hypothetical brokers", "disclaimer": "All prices are illustrative and hypothetical, not real quotes, forecasts, or results.", "hypothetical": true}]$q$::jsonb
   and coalesce(interactive_config,'null'::jsonb) = $q${"scenarios": [{"options": ["Trust the logo on their homepage", "Look up the license on the regulator's official website", "Ask in a comment section", "Check how many ads they run"], "question": "What is the safest way to check a broker's regulation?", "explanation": "Always verify the license directly with the regulator, since anyone can put a logo on a website.", "correctIndex": 1}, {"options": ["$7", "$10", "$17", "$70"], "question": "Hypothetically, Broker B charges a $0.10 spread plus $7 commission per standard lot. What is the cost for 1 standard lot?", "explanation": "$0.10 × 100 oz = $10 spread, plus $7 commission = $17.", "correctIndex": 2}, {"options": ["A cents account option", "Clear fee table", "A promise of guaranteed monthly returns", "Negative balance protection"], "question": "Which of these is a red flag?", "explanation": "No legitimate provider can guarantee returns. That is a major red flag.", "correctIndex": 2}]}$q$::jsonb) as ok from public.lessons where id = 'b123eaf2-b4fa-4ef0-8a07-bdaa190a3286'
union all
select 'types-of-orders' as slug, (slug = 'types-of-orders'
   and title = $q$Types of Orders$q$
   and md5(content) = '9eea6474125cb8c3b62151450103b5eb'
   and learning_objective is not distinct from $q$Know the main order types and how to attach a stop loss and take profit.$q$
   and key_takeaways = $q$["Market orders fill immediately; limit and stop orders wait for a specific price.", "Attach a stop loss to every trade when you place it; a take profit is optional but planned.", "Fast markets can cause slippage, so know every order type before you use it, and start with the smallest size."]$q$::jsonb
   and coalesce(examples,'null'::jsonb) = $q$[{"note": "Convention note: GFX lessons treat a $0.01 move in XAUUSD as 1 pip, and 1 standard lot as 100 oz, so a $0.01 move = $1 per standard lot. Many brokers define a gold pip differently (often $0.10) and contract sizes can vary. Always check your own broker's contract specifications.", "steps": ["Hypothetical: XAUUSD at 2,350.00; your plan wants to buy a pullback to 2,345.00.", "Order: buy limit at 2,345.00, stop loss 2,340.00 ($5.00 risk per oz), take profit 2,355.00 ($10.00 target per oz).", "Size from 1% risk on a hypothetical $1,000 account: $10 ÷ $5 = 0.02 lot (2 oz).", "If filled and stopped: −$10 (1%). If target hit: +$20 before costs. Illustrative only, not a result."], "title": "Placing a buy limit with SL and TP", "disclaimer": "All prices are illustrative and hypothetical, not real quotes, forecasts, or results.", "hypothetical": true}]$q$::jsonb
   and coalesce(interactive_config,'null'::jsonb) = $q${"scenarios": [{"options": ["Buy stop", "Buy limit", "Sell limit", "Market sell"], "question": "You want to buy only if gold pulls back below the current price. Which order?", "explanation": "A buy limit is placed below the current price to buy a pullback.", "correctIndex": 1}, {"options": ["$5", "$10", "$100", "$1,000"], "question": "Hypothetical: entry 2,345.00, SL 2,340.00, 0.02 lot (2 oz). What is the planned loss if stopped?", "explanation": "$5.00 stop distance × 2 oz = $10, which is 1% of a $1,000 account.", "correctIndex": 1}, {"options": ["Only on big trades", "Add it later if price goes against you", "Every trade, attached when placed", "Not needed on a small account"], "question": "What is the GFX rule for stop losses?", "explanation": "Every trade gets a stop loss when it is placed, even on a small cents account, to build the habit.", "correctIndex": 2}]}$q$::jsonb) as ok from public.lessons where id = 'c7eaf0f2-c415-4b9a-97c9-84f0095a721a'
union all
select 'candlestick-patterns' as slug, (slug = 'candlestick-patterns'
   and title = $q$Candlestick Patterns$q$
   and md5(content) = 'a5841a999bb1415134e5479bf8087fc6'
   and learning_objective is not distinct from $q$Recognize a few common candlestick patterns and understand their limits.$q$
   and key_takeaways = $q$["Patterns like doji, hammer, shooting star and engulfing describe buyer/seller shifts.", "Patterns matter more at key levels and with confirmation, and they still fail often.", "Use patterns as one input in a written plan with a stop loss and max 1% risk."]$q$::jsonb
   and coalesce(examples,'null'::jsonb) = $q$[{"note": "All prices are illustrative and hypothetical, not real quotes, forecasts, or results.", "steps": ["Gold has fallen to an area near 2,330.00 that acted as support before (hypothetical).", "A 1-hour candle: Open 2,333.00, Low 2,326.00, Close 2,334.50, High 2,335.00 → small body near the top, long lower wick = hammer shape.", "A trader's plan might consider a long only if the next candle closes higher, with a stop loss below the wick (e.g. 2,325.00).", "If price instead breaks below 2,325.00, the stop loss closes the trade at a planned, limited loss."], "title": "A hypothetical hammer at support", "disclaimer": "All prices are illustrative and hypothetical, not real quotes, forecasts, or results.", "hypothetical": true}]$q$::jsonb
   and coalesce(interactive_config,'null'::jsonb) = $q${"rounds": 5, "patterns": [{"id": "bullish-engulfing", "tip": "Most powerful at support zones or after a downtrend. Confirm with the next candle going up before entering.", "desc": "A small red candle followed by a large green candle that completely covers it. Shows buyers took over aggressively from sellers.", "name": "Bullish Engulfing", "ohlc": [{"c": 50, "h": 58, "l": 48, "o": 55}, {"c": 63, "h": 65, "l": 44, "o": 46}], "type": "bullish", "signal": "Strong Buy"}, {"id": "bearish-engulfing", "tip": "Most powerful at resistance zones or after an uptrend. Wait for confirmation before shorting.", "desc": "A small green candle followed by a large red candle that completely covers it. Shows sellers took over aggressively from buyers.", "name": "Bearish Engulfing", "ohlc": [{"c": 50, "h": 52, "l": 43, "o": 45}, {"c": 38, "h": 56, "l": 36, "o": 54}], "type": "bearish", "signal": "Strong Sell"}, {"id": "hammer", "tip": "Only valid at support or after a downtrend. The longer the lower wick, the stronger the signal.", "desc": "Long lower wick, small body near the top. Sellers pushed price down hard but buyers fought back and closed near the high.", "name": "Hammer", "ohlc": [{"c": 51, "h": 54, "l": 30, "o": 52}], "type": "bullish", "signal": "Bullish Reversal"}, {"id": "shooting-star", "tip": "Only valid at resistance or after an uptrend. The longer the upper wick, the stronger the signal.", "desc": "Long upper wick, small body near the bottom. Buyers pushed price up hard but sellers took over and closed near the low.", "name": "Shooting Star", "ohlc": [{"c": 49, "h": 70, "l": 46, "o": 48}], "type": "bearish", "signal": "Bearish Reversal"}, {"id": "doji", "tip": "By itself, a doji just means indecision. Watch the next candle — if it breaks in one direction, follow it.", "desc": "Open and close are almost equal. Neither buyers nor sellers won — the market is undecided about direction.", "name": "Doji", "ohlc": [{"c": 50, "h": 62, "l": 38, "o": 50}], "type": "neutral", "signal": "Indecision"}, {"id": "pin-bar", "tip": "One of the most traded patterns in price action. Always trade in the direction of the rejection wick.", "desc": "A candle with a very long wick and a tiny body — shows strong rejection of a price level by the market.", "name": "Pin Bar", "ohlc": [{"c": 51, "h": 54, "l": 28, "o": 52}], "type": "bullish", "signal": "Reversal Signal"}], "scenarios": [{"options": ["Strong guaranteed uptrend", "Indecision, with open and close nearly equal", "Market closed", "A broker error"], "question": "What does a doji usually indicate?", "explanation": "A doji has nearly equal open and close, suggesting indecision.", "correctIndex": 1}, {"options": ["Long upper wick after a rise", "Small body near the top with a long lower wick after a decline", "No wicks at all", "A huge red body"], "question": "Which describes a hammer?", "explanation": "A hammer has a long lower wick and small body near the top, usually after a decline.", "correctIndex": 1}, {"options": ["Above the high at 2,335.00", "Below the hammer's wick, around 2,325.00", "No stop loss needed", "At the entry price"], "question": "In the hypothetical example, where is the stop loss placed?", "explanation": "The stop goes below the wick so the trade closes at a planned loss if the pattern fails.", "correctIndex": 1}], "lookalikes": {"hammer": ["pin-bar"], "pin-bar": ["hammer"]}}$q$::jsonb) as ok from public.lessons where id = 'bf0e27f5-ab9b-4e63-8f77-8b0a692476e0';

-- 2) Diagnostic rows. Expect 8 rows, ok = true.
select 'platform_demo_purpose' as key, (question = $q$You've never used MT5 and want to learn where the Buy, Sell and SL/TP buttons are before your first real trade. What's a no-risk way to do that?$q$ and options = $q$["Explore the free MT5 demo (optional practice tool)", "Maximum leverage", "Place a big real trade to learn fast", "Skip learning the buttons and guess"]$q$::jsonb and explanation is not distinct from $q$The MT5 demo uses virtual money, so it's a no-risk way to learn the app's buttons. It won't train your emotions; for that, GFX suggests a small cents account with max 1% risk and a stop loss on every trade.$q$ and correct_index = 0) as ok from public.diagnostic_questions where id = '3a89b300-bdbb-445e-9a4b-4420ea579057'
union all
select 'setups_trading_plan_purpose' as key, (question = $q$You're about to enter a trade but haven't decided your stop loss, target, or risk amount in advance. What is this missing?$q$ and options = $q$["A cents account", "The spread", "A trading plan", "A broker account"]$q$::jsonb and explanation is not distinct from $q$A trading plan defines entry, SL/TP, and risk rules in advance — exactly what's missing here.$q$ and correct_index = 2) as ok from public.diagnostic_questions where id = '9de5a6fa-a5bb-457d-b8c1-1a330f7dfdcb'
union all
select 'risk_management_stop_loss' as key, (question = $q$Is it ever okay to skip your stop loss if you're very confident about a trade?$q$ and options = $q$["Only on small cents accounts", "No — never trade without a stop loss, no exceptions", "Yes, if experienced", "Yes, always skip it on Gold"]$q$::jsonb and explanation is not distinct from $q$A stop loss is non-negotiable regardless of confidence level.$q$ and correct_index = 1) as ok from public.diagnostic_questions where id = 'a2e0f08f-7098-49a6-9ea2-3d0b5dae0688'
union all
select 'gold_news_release' as key, (question = $q$A major US economic report is due in 5 minutes and Gold is already moving fast. As a beginner trading a small cents account, what is the most sensible approach?$q$ and options = $q$["Open a large trade before the release to catch the move", "Remove your stop loss so the spike doesn't close your trade", "Avoid opening new trades until the release has passed and spreads settle", "Double your usual risk because volatility means opportunity"]$q$::jsonb and explanation is not distinct from $q$Around major news, Gold can spike and spreads can widen sharply. Beginners are safer waiting; risk stays at max 1% with a stop loss on every trade.$q$ and correct_index = 2) as ok from public.diagnostic_questions where id = 'ebdfe0f7-704f-4997-86f2-7de6a461e2f9'
union all
select 'journaling_weekly_review' as key, (question = $q$At the end of the week you review your trading journal. Which measure best shows whether you are improving as a beginner?$q$ and options = $q$["How many trades followed every rule in your plan", "Your account balance compared with last week", "How many trades you opened", "Your single biggest winning trade"]$q$::jsonb and explanation is not distinct from $q$Single results are partly luck. Rule-following (stop loss on every trade, max 1% risk, plan followed) is under your control and shows real progress.$q$ and correct_index = 0) as ok from public.diagnostic_questions where id = '04d9eaf5-ca4c-42cf-bbdd-9e10560dd28a'
union all
select 'setups_lot_size_from_stop' as key, (question = $q$Hypothetically, your account is $1,000 and you risk max 1% per trade. Your planned Gold stop distance is $2.50. With 0.01 lot = 1 oz (a $0.01 move = $1 per standard lot), what lot size fits the rule?$q$ and options = $q$["0.01 lot", "0.04 lot", "0.40 lot", "4 lots"]$q$::jsonb and explanation is not distinct from $q$1% of $1,000 = $10. A $2.50 stop on 0.01 lot (1 oz) risks $2.50, so $10 ÷ $2.50 = 4 → 0.04 lot. Check: 4 oz × $2.50 = $10.$q$ and correct_index = 1) as ok from public.diagnostic_questions where id = '8c7292b0-f870-49b3-8d21-84bf04d75812'
union all
select 'psychology_moving_stop' as key, (question = $q$Your trade is moving toward your stop loss, so you move the stop further away to 'give it more room'. What is the main problem?$q$ and options = $q$["Nothing, it's a normal adjustment", "It reduces your risk", "It increases your risk beyond what you planned", "It guarantees the trade will recover"]$q$::jsonb and explanation is not distinct from $q$Moving a stop further away means a bigger possible loss than your plan allowed. Many traders only move stops in the direction that reduces risk.$q$ and correct_index = 2) as ok from public.diagnostic_questions where id = '8b7fc3b0-032f-4495-a7b8-2650a448a946'
union all
select 'platform_attach_stop_loss' as key, (question = $q$When should you set the stop loss on a new trade?$q$ and options = $q$["When you place the order, as part of the order", "Only after the trade starts losing", "At the end of the day", "Only on big accounts, not on a small cents account"]$q$::jsonb and explanation is not distinct from $q$Attach the stop loss when you place the order so the trade is protected from the first second, and do it on every trade, even on a small cents account, to build the habit.$q$ and correct_index = 0) as ok from public.diagnostic_questions where id = 'd5e7864f-7214-4b98-823d-202e9192ca7c';

